# hypothesis: A TypeIs guard declared in an enclosing function still narrows a tuple argument in the positive branch and the remaining union in the negative branch, and narrows a dataclass attribute the same way.
from dataclasses import dataclass
from typing import TypeIs, reveal_type


@dataclass
class Box:
    value: int | str


def is_int(v: object) -> TypeIs[int]:
    return isinstance(v, int)


def outer() -> str:
    def is_all_int(v: tuple[int | str, ...]) -> TypeIs[tuple[int, ...]]:
        return all(isinstance(x, int) for x in v)

    def check(t: tuple[int | str, ...]) -> str:
        if is_all_int(t):
            reveal_type(t)
            return 'ints'
        reveal_type(t)
        return 'mixed'

    return check((1, 2)) + ',' + check(('a', 2))


def describe(box: Box) -> str:
    if is_int(box.value):
        reveal_type(box.value)
        return 'int ' + str(box.value + 1)
    reveal_type(box.value)
    return 'other ' + box.value


assert outer() == 'ints,mixed'
assert describe(Box(3)) == 'int 4'
assert describe(Box('x')) == 'other x'
